PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      password TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'worker' CHECK(role IN ('owner', 'worker')),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE workers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER UNIQUE,
      name TEXT NOT NULL,
      phone TEXT,
      email TEXT,
      skills TEXT NOT NULL DEFAULT 'photographer' CHECK(skills IN ('photographer', 'retoucher', 'both')),
      rate_per_gig REAL DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
    );
CREATE TABLE gigs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      client_name TEXT NOT NULL,
      client_email TEXT,
      client_phone TEXT,
      gig_date DATE NOT NULL,
      location TEXT,
      description TEXT,
      total_amount REAL NOT NULL DEFAULT 0,
      photographer_split REAL DEFAULT 30,
      retoucher_split REAL DEFAULT 30,
      status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'in_progress', 'completed', 'cancelled')),
      invoice_reference TEXT,
      zoho_invoice_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE gig_workers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      gig_id INTEGER NOT NULL,
      worker_id INTEGER NOT NULL,
      role TEXT NOT NULL CHECK(role IN ('photographer', 'retoucher')),
      custom_split REAL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (gig_id) REFERENCES gigs(id) ON DELETE CASCADE,
      FOREIGN KEY (worker_id) REFERENCES workers(id) ON DELETE CASCADE
    );
CREATE TABLE invoices (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      gig_id INTEGER,
      invoice_number TEXT NOT NULL,
      client_name TEXT NOT NULL,
      amount REAL NOT NULL,
      tax_amount REAL DEFAULT 0,
      total_amount REAL NOT NULL,
      due_date DATE,
      status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'paid', 'partial', 'overdue', 'cancelled')),
      source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('zoho', 'manual')),
      zoho_invoice_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP, amount_paid REAL DEFAULT 0, balance REAL DEFAULT 0, client_email TEXT, client_phone TEXT,
      FOREIGN KEY (gig_id) REFERENCES gigs(id) ON DELETE SET NULL
    );
CREATE TABLE worker_payments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      gig_id INTEGER NOT NULL,
      worker_id INTEGER NOT NULL,
      amount REAL NOT NULL,
      payment_date DATE NOT NULL,
      payment_method TEXT DEFAULT 'cash' CHECK(payment_method IN ('cash', 'bank_transfer', 'mobile_money', 'card', 'other')),
      reference_number TEXT,
      status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'paid', 'cancelled')),
      notes TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (gig_id) REFERENCES gigs(id) ON DELETE CASCADE,
      FOREIGN KEY (worker_id) REFERENCES workers(id) ON DELETE CASCADE
    );
CREATE TABLE expense_categories (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      is_default INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE expenses (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      category_id INTEGER,
      description TEXT NOT NULL,
      amount REAL NOT NULL,
      expense_date DATE NOT NULL,
      gig_id INTEGER,
      receipt_reference TEXT,
      notes TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (category_id) REFERENCES expense_categories(id) ON DELETE SET NULL,
      FOREIGN KEY (gig_id) REFERENCES gigs(id) ON DELETE SET NULL
    );
CREATE TABLE zoho_settings (
      id INTEGER PRIMARY KEY DEFAULT 1,
      client_id TEXT,
      client_secret TEXT,
      refresh_token TEXT,
      organization_id TEXT,
      region TEXT DEFAULT 'com',
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE client_payments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    gig_id INTEGER NOT NULL,
    invoice_id INTEGER,
    amount REAL NOT NULL,
    payment_date DATE NOT NULL,
    payment_method TEXT DEFAULT 'cash',
    reference_number TEXT,
    notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (gig_id) REFERENCES gigs(id) ON DELETE CASCADE,
    FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE SET NULL
  );
CREATE INDEX idx_gigs_date ON gigs(gig_date);
CREATE INDEX idx_gigs_status ON gigs(status);
CREATE INDEX idx_worker_payments_gig ON worker_payments(gig_id);
CREATE INDEX idx_worker_payments_worker ON worker_payments(worker_id);
CREATE INDEX idx_expenses_date ON expenses(expense_date);
CREATE INDEX idx_invoices_status ON invoices(status);
CREATE INDEX idx_client_payments_gig ON client_payments(gig_id);
COMMIT;
